(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.02+t*0.3)*15 + Math.cos(y*0.015-t*0.2)*10;
  const w1y = Math.cos(y*0.02-t*0.25)*15 + Math.sin(x*0.018+t*0.35)*10;
  const wx = w1x + Math.sin((x+w1x)*0.03-t*0.5)*8 + Math.cos((y+w1y)*0.025+t*0.4)*6;
  const wy = w1y + Math.cos((y+w1y)*0.03+t*0.45)*8 + Math.sin((x+w1x)*0.02-t*0.55)*6;
