  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,0.5],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.7],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,0.4],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.8],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,0.3],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.6],
    [60+Math.sin(t*0.7+3)*70,40+Math.cos(t*0.3+1)*50,0.11,2.1,0.55],
    [420+Math.cos(t*0.45+2)*60,200+Math.sin(t*0.65+4)*40,0.13,1.8,0.45],
    [200+Math.sin(t*0.55)*110,220+Math.cos(t*0.75+2)*70,0.075,2.4,0.65],
    [300+Math.cos(t*0.85+3)*90,30+Math.sin(t*0.45+1)*60,0.095,1.6,0.35]
  ];
  let aS=0,iS=0,dif=0;
  for(const[sX,sY,f,sp,amp]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*amp;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*amp;
    dif+=Math.sin(d*f*1.3-t*sp*0.4+2.0)*amp*0.5;
  }
  const act=aS/10,inh=iS/10,difN=dif/10;
  const bg=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1)+Math.sin(sx*0.05+sy*0.01-t*0.6))/3+Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2+Math.sin(sx*0.08+t*1.8)*Math.cos(sy*0.06-t*1.3)*0.15;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const spiral=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4+Math.sin(dist*0.07-ang*2+t*0.8)*0.15+Math.sin(dist*0.03+ang*5-t*2.0)*0.1;
