  const reaction=Math.tanh((act*0.6-inh*0.5+bg*0.25+spiral*0.35+difN*0.2+detail)*2.0);
  const reaction2=Math.tanh((act*0.4+inh*0.3-bg*0.2+spiral*0.15)*2.5);
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5+Math.sin(sx*0.2-t*0.8)*Math.cos(sy*0.18+t*0.6)*0.3)*1.5)*0.25;
  const breath=0.95+Math.sin(t*0.3)*0.05;
  const blend=(reaction*0.6+cell*0.2+reaction2*0.2)*breath;
  const v=blend*0.5+0.5;
  const pal=[[5,10,45],[12,45,85],[18,85,120],[25,135,130],[55,165,115],[140,185,80],[210,190,60],[230,150,55],[210,100,60],[170,55,55],[120,30,50],[65,15,45],[30,12,50],[5,10,45]];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
