  const chroma=reaction2*0.03;
  const r=(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*lum*edge+chroma*80;
  const g=(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*lum*edge+chroma*30;
  const b=(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*lum*edge-chroma*50;
  return[Math.min(255,Math.max(0,r))|0,Math.min(255,Math.max(0,g))|0,Math.min(255,Math.max(0,b))|0];
}
